<template>
  <section id="company-product-directory" :class="{ compact }" aria-labelledby="company-products-title">
    <div class="directory-wrap">
      <div v-if="compact" class="directory-heading"><div><p class="directory-kicker">跃科产品体系</p><h2 id="company-products-title">围绕学校的工作，找到合适的产品。</h2></div><RouterLink to="/products">查看全部产品 →</RouterLink></div>
      <template v-if="compact"><div class="domain-overview"><article v-for="domain in publishedDomains" :key="domain.key"><h3><RouterLink :to="domainLink(domain.key)">{{ domain.name }} →</RouterLink></h3><ul><li v-for="product in productsInDomain(domain.key)" :key="product.key"><RouterLink :to="product.path || consultLink(product.key)">{{ product.name }}</RouterLink></li></ul></article></div><nav v-if="otherDomains.length" class="other-domains" aria-label="其他建设领域"><span>其他建设需求</span><RouterLink v-for="domain in otherDomains" :key="domain.key" :to="domainLink(domain.key)">{{ domain.name }} →</RouterLink></nav></template>
      <div v-else class="directory-layout">
        <aside class="directory-sidebar"><h2 id="company-products-title" class="sr-only">产品目录</h2><nav aria-label="产品业务领域"><RouterLink v-for="domain in PRODUCT_DOMAINS" :key="domain.key" :to="domainLink(domain.key)" :aria-current="selected === domain.key ? 'location' : undefined"><img :src="icon(domain.icon)" alt="" width="26" height="26">{{ domain.name }}</RouterLink></nav><div class="sidebar-note"><p>用数字化，<br>助力学校更好地开展工作。</p><RouterLink to="/services/delivery">了解实施服务 →</RouterLink></div></aside>
        <div class="product-groups"><section v-for="domain in publishedDomains" :id="`domain-${domain.key}`" :key="domain.key" :aria-labelledby="`title-${domain.key}`"><header class="group-heading"><h2 :id="`title-${domain.key}`">{{ domain.name }}</h2></header><article v-for="product in productsInDomain(domain.key)" :key="product.key" class="directory-product"><img class="product-icon" :src="icon(product.icon)" alt="" width="32" height="32"><div class="product-copy"><div class="product-title"><h3><RouterLink :to="product.path || consultLink(product.key)">{{ product.name }}</RouterLink></h3><nav v-if="product.children.length" class="child-products" :aria-label="`${product.name}业务中心`"><RouterLink v-for="slug in product.children" :key="slug" :to="`/products/${slug}`">{{ OFFICIAL_SALES_PAGE_MAP[`/products/${slug}`].navTitle }}</RouterLink></nav></div><p v-if="product.introduction">{{ product.introduction }}</p><RouterLink v-else class="product-consult" :to="consultLink(product.key)">沟通产品与建设范围 →</RouterLink></div><RouterLink class="product-arrow" :to="product.path || consultLink(product.key)" :aria-label="`${product.path ? '了解' : '咨询'}${product.name}`">›</RouterLink></article></section><section v-if="otherDomains.length" class="domain-needs" aria-labelledby="domain-needs-title"><h2 id="domain-needs-title">其他建设需求</h2><div v-for="domain in otherDomains" :id="`domain-${domain.key}`" :key="domain.key" class="domain-need-row"><h3>{{ domain.name }}</h3><RouterLink to="/contact" :aria-label="`咨询${domain.name}建设需求`">沟通需求 →</RouterLink></div></section></div>
      </div>
    </div>
  </section>
</template>
<script setup>
import { computed, ref, watch, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { PRODUCT_DOMAINS, productsInDomain } from '../../config/companyProducts.js'
import { OFFICIAL_SALES_PAGE_MAP } from '../../config/officialSalesPages.js'
const props = defineProps({ compact: Boolean })
const route = useRoute()
const publishedDomains = computed(() => PRODUCT_DOMAINS.filter(domain => productsInDomain(domain.key).length))
const otherDomains = computed(() => PRODUCT_DOMAINS.filter(domain => !productsInDomain(domain.key).length))
// URL fragments are not sent to the static server; align the initial hydration,
// then select the requested domain after mounting.
const activeHash = ref('')
onMounted(() => { activeHash.value = route.hash })
watch(() => route.hash, hash => { activeHash.value = hash })
const selected = computed(() => PRODUCT_DOMAINS.find(domain => activeHash.value === `#domain-${domain.key}`)?.key || 'teaching')
function domainLink(domain) { return { path: '/products', hash: `#domain-${domain}` } }
function consultLink(product) { return { path: '/contact', query: { product } } }
function icon(name) { return `/official-site/icons/${name}.svg` }
</script>
