</style>
<style scoped>
.domain-overview{grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}.other-domains{display:flex;flex-wrap:wrap;align-items:center;gap:8px 28px;margin-top:30px;padding-top:20px;border-top:1px solid #dde6ef;font-size:14px}.other-domains>span{color:#62768e}.other-domains a{padding:10px 0}.domain-needs{border-top:1px solid #dde6ef;padding-top:22px}.domain-needs>h2{font-size:16px!important;color:#62768e!important;margin-bottom:12px!important}.domain-need-row{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:10px 0;scroll-margin-top:100px}.domain-need-row h3{font-size:16px!important;font-weight:500!important}.domain-need-row a{padding:10px 0;color:#2469bd!important;font-size:14px;white-space:nowrap}.directory-sidebar nav{overflow-x:auto;overflow-y:hidden}.directory-sidebar nav a{flex-shrink:0}@media(max-width:720px){.domain-overview{grid-template-columns:1fr}.other-domains{gap:6px 20px}.other-domains>span{width:100%}.domain-need-row{gap:12px}.domain-need-row h3{font-size:15px!important}}
